package cn.deque;
import android.database.*;import android.database.sqlite.*;import android.content.*;import org.json.*;import java.util.*;
final class Backup {
 static final String[] TABLES={"queues","tasks","preferences"};
 static JSONObject exportData(SQLiteDatabase db)throws Exception{JSONObject root=new JSONObject();root.put("format","deque-backup");root.put("version",1);root.put("exportedAt",System.currentTimeMillis());db.beginTransaction();try{for(String table:TABLES){JSONArray rows=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM "+table,null)){while(c.moveToNext()){JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++)row.put(c.getColumnName(i),c.isNull(i)?JSONObject.NULL:c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));rows.put(row);}}root.put(table,rows);}db.setTransactionSuccessful();}finally{db.endTransaction();}return root;}
 static long number(JSONObject row,String key)throws Exception{Object value=row.get(key);if(!(value instanceof Integer)&&!(value instanceof Long))throw new Exception("无效数字："+key);return ((Number)value).longValue();}
 static String text(JSONObject row,String key)throws Exception{Object value=row.get(key);if(!(value instanceof String))throw new Exception("无效文本："+key);return (String)value;}
 static void require(boolean valid)throws Exception{if(!valid)throw new Exception("备份数据格式不正确");}
 static void validate(JSONObject root)throws Exception{require("deque-backup".equals(root.getString("format"))&&number(root,"version")==1);JSONArray qs=root.getJSONArray("queues"),ts=root.getJSONArray("tasks"),ps=root.getJSONArray("preferences");require(qs.length()<=10000&&ts.length()<=100000);Set<String> ids=new HashSet<>(),tasks=new HashSet<>(),prefs=new HashSet<>();for(int i=0;i<qs.length();i++){JSONObject q=qs.getJSONObject(i);String id=text(q,"id");require(!id.isEmpty()&&ids.add(id)&&!text(q,"name").trim().isEmpty());require(number(q,"tail")>=0&&number(q,"tail")<=1&&number(q,"deleted")>=0&&number(q,"deleted")<=1&&number(q,"reminderMinutes")>=0&&number(q,"reminderMinutes")<=5256000);number(q,"updated");}for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);require(tasks.add(text(t,"id"))&&!t.getString("id").isEmpty()&&ids.contains(text(t,"queueId"))&&!text(t,"title").trim().isEmpty());text(t,"notes");number(t,"position");number(t,"updated");require(number(t,"deadline")>=0&&number(t,"state")>=0&&number(t,"state")<=1);if(!t.isNull("completed"))require(number(t,"completed")>=0);}for(int i=0;i<ps.length();i++){JSONObject pref=ps.getJSONObject(i);require(prefs.add(text(pref,"key")));number(pref,"value");}}
 static void importData(SQLiteDatabase db,JSONObject root)throws Exception{validate(root);db.beginTransaction();try{Map<String,String> ids=new HashMap<>();JSONArray qs=root.getJSONArray("queues"),ts=root.getJSONArray("tasks");for(int i=0;i<qs.length();i++){JSONObject q=qs.getJSONObject(i);String newId=UUID.randomUUID().toString();ids.put(q.getString("id"),newId);ContentValues v=values(q,new String[]{"name","tail","updated","deleted","reminderMinutes"});v.put("id",newId);v.put("position",q.optLong("position",0));db.insertOrThrow("queues",null,v);}for(int i=0;i<ts.length();i++){JSONObject t=ts.getJSONObject(i);ContentValues v=values(t,new String[]{"title","position","state","updated","completed","notes","deadline"});v.put("id",UUID.randomUUID().toString());v.put("queueId",ids.get(t.getString("queueId")));db.insertOrThrow("tasks",null,v);}JSONArray ps=root.getJSONArray("preferences");for(int i=0;i<ps.length();i++)db.insertWithOnConflict("preferences",null,values(ps.getJSONObject(i),new String[]{"key","value"}),SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static ContentValues values(JSONObject row,String[] keys)throws Exception{ContentValues v=new ContentValues();for(String key:keys){Object value=row.get(key);if(value==JSONObject.NULL)v.putNull(key);else if(value instanceof Number)v.put(key,((Number)value).longValue());else v.put(key,(String)value);}return v;}
}
